    async Task AddAnime()
    {
        var query=new TextBox{PlaceholderText="Название на русском / English / 日本語"};var results=new StackPanel{Spacing=8};var info=Paper.Text("Введите от двух символов — появятся варианты из Shikimori.",12,Paper.Muted);
        var panel=new DockPanel();var dialog=Paper.Dialog(this,"Добавить аниме",panel,700,590);var cancellation=new CancellationTokenSource();CancellationTokenSource? request=null;int generation=0;Anime? created=null;bool closed=false;
        async Task Find(){request?.Cancel();request?.Dispose();request=CancellationTokenSource.CreateLinkedTokenSource(cancellation.Token);var token=request.Token;int current=++generation;var text=query.Text?.Trim()??"";if(text.Length<2){results.Children.Clear();return;}info.Text="Ищу в Shikimori…";try{await Task.Delay(400,token);var entries=await Catalog.Search(text,token);if(closed||current!=generation)return;results.Children.Clear();foreach(var entry in entries){var row=new DockPanel();var sample=new Anime{CatalogId=entry.Id,Title=entry.Title,CoverUrl=entry.CoverUrl};var cover=covers.Image(sample,token,45,65);cover.Margin=new Thickness(0,0,12,0);DockPanel.SetDock(cover,Dock.Left);row.Children.Add(cover);row.Children.Add(Paper.Stack(Paper.Text(entry.Title,16),Paper.Text(entry.Names,11,Paper.Muted),Paper.Text(entry.Info,11,Paper.Muted)));var button=new Button{Content=row,HorizontalAlignment=HorizontalAlignment.Stretch,HorizontalContentAlignment=HorizontalAlignment.Stretch,Background=Paper.Sheet,Padding=new Thickness(12)};button.Click+=async(_,_)=>{try{created=store.Add(entry);dialog.Close();}catch(Exception e){await Paper.Message(dialog,e.Message);}};results.Children.Add(button);}info.Text=entries.Count==0?"Ничего не найдено. Можно добавить вручную.":"Выберите нужный сезон.";}catch(OperationCanceledException){}catch{if(!closed&&current==generation)info.Text="Каталог недоступен. Повторите поиск или добавьте вручную.";}}
        var head=Paper.Stack(Paper.Text("Новая история",27),query,info);DockPanel.SetDock(head,Dock.Top);panel.Children.Add(head);
        var actions=Paper.Actions(Paper.AsyncButton("Найти",Find),Paper.AsyncButton("Добавить вручную",async()=>{try{created=store.AddManual(query.Text??"");dialog.Close();}catch(Exception e){await Paper.Message(dialog,e.Message);}}),Paper.Button("Отмена",()=>dialog.Close()));DockPanel.SetDock(actions,Dock.Bottom);panel.Children.Add(actions);panel.Children.Add(Paper.Scroll(results));query.TextChanged+=async(_,_)=>await Find();dialog.Closed+=(_,_)=>{closed=true;cancellation.Cancel();request?.Cancel();};dialog.Opened+=(_,_)=>query.Focus();await Modal(dialog);if(created!=null)await Edit(created);
    }
    async Task EditAnime(Anime anime)
