        var tokenSource=new CancellationTokenSource();bool closed=false;var body=new StackPanel{Spacing=12};var root=new DockPanel();var dialog=Paper.Dialog(this,anime.Title,root,790,760);
        var title=new TextBox{Text=anime.Title};var watched=new TextBox{Text=anime.Watched.ToString()};var total=new TextBox{Text=anime.Total.ToString()};var statusChoice=Paper.Choice(MalImport.StatusLabels,Array.IndexOf(MalImport.StatusKeys,anime.Status),140);var score=Paper.Choice(Ratings.Labels,anime.Score,100);var notes=new TextBox{Text=anime.Notes,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=100,MaxHeight=220};var error=Paper.Text("",12,Brushes.Firebrick);
