        AddAction(Paper.AsyncButton("В виджет",()=>Act(()=>store.SetWidget(anime.Id,store.Widget.Style))));
        AddAction(Paper.AsyncButton("Удалить",async()=>{if(await Paper.Message(dialog,"Удалить «"+anime.Title+"» из библиотеки? Предыдущая версия сохраняется в library.xml.bak.","Удаление",true)){store.Remove(anime);dialog.Close();}}));
        var footer=Paper.Stack(error,actions);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);root.Children.Add(Paper.Scroll(body));
        var hero=new DockPanel();var cover=covers.Image(anime,tokenSource.Token,120,175);cover.Margin=new Thickness(0,0,20,0);DockPanel.SetDock(cover,Dock.Left);hero.Children.Add(cover);hero.Children.Add(Paper.Stack(Paper.Text("МОЯ БИБЛИОТЕКА",11,Paper.Muted),Paper.Text(anime.Title,27),Paper.Text(string.Join(" · ",new[]{anime.English,anime.Japanese,anime.Romaji}.Where(s=>!string.IsNullOrWhiteSpace(s)&&s!=anime.Title).Distinct()),12,Paper.Muted),Paper.Text(anime.Genres.Replace("|"," · "),12,Paper.Muted)));body.Children.Add(hero);
        var controls=new Grid{ColumnDefinitions=new ColumnDefinitions("*,*,*,*"),ColumnSpacing=8};var fields=new Control[]{Paper.Field("Статус",statusChoice),Paper.Field("Просмотрено",watched),Paper.Field("Всего · 0 неизвестно",total),Paper.Field("Моя оценка",score)};for(int i=0;i<fields.Length;i++){Grid.SetColumn(fields[i],i);controls.Children.Add(fields[i]);}
