        body.Children.Add(Paper.Card(Paper.Stack(Paper.Text("Прогресс и впечатления",21),controls,Paper.Button("＋ Следующая серия",()=>{if(int.TryParse(watched.Text,out var w)&&int.TryParse(total.Text,out var t)&&w>=0&&(t==0||w<t)){watched.Text=(w+1).ToString();if(t>0&&w+1==t)statusChoice.SelectedIndex=1;}}),Paper.Field("Личная заметка",notes),new Expander{Header="Название в моей библиотеке",Content=title})));
        body.Children.Add(BuildArcs(anime,dialog,tokenSource.Token));var description=Paper.Text(anime.CatalogId>0?"Загружаю описание…":"Нет связи с Shikimori.",13,Paper.Muted);body.Children.Add(Paper.Text("Об аниме",22));body.Children.Add(description);
        var sequelRows=new StackPanel();var sequels=new Expander{Header="Продолжения",Content=sequelRows};body.Children.Add(sequels);bool loaded=false;
        sequels.Expanding+=async(_,_)=>{if(loaded||anime.CatalogId<=0)return;loaded=true;sequelRows.Children.Add(Paper.Text("Загружаю…",12,Paper.Muted));try{var links=await Catalog.Sequels(new[]{anime.CatalogId},tokenSource.Token);if(closed)return;sequelRows.Children.Clear();if(links.TryGetValue(anime.CatalogId,out var entries))foreach(var entry in entries){var owned=Ratings.Find(store.Library,entry);sequelRows.Children.Add(Paper.Card(Paper.Stack(Paper.Text(entry.Title,16),Paper.AsyncButton(owned==null?"＋ В планы":"Карточка",async()=>{var found=Ratings.Find(store.Library,entry);if(found==null)store.Add(entry);else await Edit(found);})))) ;}if(sequelRows.Children.Count==0)sequelRows.Children.Add(Paper.Text("Продолжений пока нет.",12));}catch{if(!closed){loaded=false;sequelRows.Children.Clear();sequelRows.Children.Add(Paper.Text("Не удалось загрузить. Сверните и раскройте для повтора.",12));}}};
        dialog.Opened+=async(_,_)=>{if(anime.CatalogId<=0)return;try{var entries=await Catalog.ByIds(new[]{anime.CatalogId},tokenSource.Token,true);if(!closed)description.Text=entries.FirstOrDefault()?.Description is {Length:>0} text?text:"Описания в каталоге нет.";}catch{if(!closed)description.Text="Описание сейчас недоступно. Личные данные можно редактировать без интернета.";}};
