    Expander BuildArcs(Anime anime,Window owner,CancellationToken token)
    {
        var catalog=ArcCatalog.Find(anime.MalId,anime.Id);var cache=store.FilePath(Path.Combine("episode-flags",anime.MalId+".xml"));var flags=catalog?.Flags??ArcData.ReadCache(cache);var rows=new StackPanel{Spacing=8};var info=Paper.Text(catalog==null?"Арки можно добавить вручную. Отметки серий доступны через Jikan.":"Локальный справочник · до серии "+flags.Items.Keys.Max()+" · источник от "+catalog.Date,12,Paper.Muted);var content=Paper.Stack(info);var section=new Expander{Header="Арки и филлеры",Content=content};var filler=new CheckBox{Content="Только филлеры"};Action render=null!;
        var actions=Paper.Actions(Paper.AsyncButton("＋ Добавить арку",async()=>{await EditArc(anime,null,owner);render();}),filler);
        if(catalog!=null)actions.Children.Add(Paper.Button("Источник ↗",()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(catalog.Source){UseShellExecute=true})));
        else{var update=Paper.AsyncButton("Загрузить отметки",async()=>{flags=await ArcData.Fetch(anime.MalId,cache,token,(page,total)=>info.Text="Загрузка отметок: "+page+" / "+total);render();});update.IsEnabled=anime.MalId>0;actions.Children.Add(update);}
        content.Children.Add(actions);content.Children.Add(rows);
        render=()=>{if(token.IsCancellationRequested)return;rows.Children.Clear();var next=anime.Watched+1;flags.Items.TryGetValue(next,out var type);rows.Children.Add(Paper.Text("Следующая серия: "+next+" · "+ArcData.Label(type),14));
            foreach(var arc in ArcCatalog.Merge(catalog,store.Arcs,anime.Id)){var episodes=ArcCatalog.Episodes(arc);var kind=ArcData.Classification(arc,flags);bool hasFiller=kind=="filler"||(arc.Type=="auto"&&episodes.Any(n=>flags.Items.TryGetValue(n,out var label)&&label=="filler"));if(filler.IsChecked==true&&!hasFiller)continue;var row=Paper.Stack(Paper.Text(arc.Name,17),Paper.Text("Серии "+ArcCatalog.Format(episodes)+" · "+ArcData.Label(kind),12,Paper.Muted),Paper.Text("Просмотрено: "+episodes.Count(n=>n<=anime.Watched)+" / "+episodes.Count+(episodes.Contains(next)?" · текущая арка":""),11,Paper.Muted),Paper.AsyncButton("Изменить",async()=>{await EditArc(anime,arc,owner);render();}));if(hasFiller&&kind!="filler")row.Children.Add(Paper.Text("Филлеры: "+ArcCatalog.Format(episodes.Where(n=>flags.Items.TryGetValue(n,out var label)&&label=="filler")),11,Paper.Muted));rows.Children.Add(Paper.Card(row));}
            if(rows.Children.Count==1)rows.Children.Add(Paper.Text("Именованных арок пока нет.",12,Paper.Muted));
            if(store.Arcs.Any(a=>a.AnimeId==anime.Id&&a.CatalogKey.Length>0))rows.Children.Add(Paper.AsyncButton("Сбросить правки справочных арок",async()=>{store.SaveArcs(store.Arcs.Where(a=>a.AnimeId!=anime.Id||a.CatalogKey=="").ToList());render();await Task.CompletedTask;}));
            var episodeRows=new StackPanel{Spacing=5};foreach(var range in ArcData.Ranges(flags)){if(filler.IsChecked==true&&range.Type!="filler")continue;episodeRows.Children.Add(Paper.Text("Серии "+range.From+"–"+range.To+" · "+ArcData.Label(range.Type),12,Paper.Muted));}rows.Children.Add(new Expander{Header="Отметки по сериям",Content=episodeRows});};
        filler.IsCheckedChanged+=(_,_)=>render();section.Expanding+=(_,_)=>render();return section;
    }
    async Task EditArc(Anime anime,AnimeArc? existing,Window owner)
    {
        var name=new TextBox{Text=existing?.Name??""};var ranges=new TextBox{Text=existing==null?"1":ArcCatalog.Format(ArcCatalog.Episodes(existing))};var type=Paper.Choice(ArcData.Labels,existing==null?0:Array.IndexOf(ArcData.Types,existing.Type),250);var panel=Paper.Stack(Paper.Field("Название арки",name),Paper.Field("Серии · например 1–12, 15, 18–24",ranges),Paper.Field("Тип",type),Paper.Text("Правки сохраняются отдельно от прогресса просмотра.",12,Paper.Muted));var dialog=Paper.Dialog(owner,"Арка",panel,550,420);
        var actions=Paper.Actions(Paper.AsyncButton("Сохранить",async()=>{var changed=new AnimeArc{Id=existing?.Id??Guid.NewGuid().ToString(),AnimeId=anime.Id,Name=(name.Text??"").Trim(),Type=ArcData.Types[Math.Max(0,type.SelectedIndex)],CatalogKey=existing?.CatalogKey??""};ArcCatalog.SetEpisodes(changed,ArcCatalog.Episodes(ranges.Text??""));ArcData.Validate(changed);if(anime.Total>0&&changed.To>anime.Total)throw new ArgumentException("Диапазон выходит за количество серий.");if(store.Arcs.Any(a=>a.AnimeId==anime.Id&&a.Id!=changed.Id&&!a.Hidden&&ArcCatalog.Episodes(a).Overlaps(ArcCatalog.Episodes(changed))))throw new ArgumentException("Серии пересекаются с другой вашей аркой.");store.SaveArcs(ArcCatalog.Replace(store.Arcs,changed));dialog.Close();await Task.CompletedTask;}),Paper.Button("Отмена",()=>dialog.Close()));
        if(existing!=null)actions.Children.Add(Paper.AsyncButton(existing.CatalogKey==""?"Удалить":"Скрыть арку",async()=>{var next=store.Arcs.Where(a=>a.AnimeId!=anime.Id||a.Id!=existing.Id).ToList();if(existing.CatalogKey!="")next.Add(new AnimeArc{Id=existing.Id,AnimeId=anime.Id,Name=existing.Name,Type=existing.Type,From=existing.From,To=existing.To,Intervals=existing.Intervals,CatalogKey=existing.CatalogKey,Hidden=true});store.SaveArcs(next);dialog.Close();await Task.CompletedTask;}));panel.Children.Add(actions);await Modal(dialog);
    }
